package com.fixmer.mared.technology.server.setup;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;import com.google.gson.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;import java.util.*;
/** Host/local and online OP views share fixed queue actions, never participant secrets or arbitrary paths. */
public final class TransitionScreen81 extends MaredScreen {
 private final Screen previous;private final boolean host;private final String root,label;private int left,w,scroll,maxScroll;private Button wait,stop,close;
 public TransitionScreen81(Screen previous,boolean host,String root,String label){super(tr("title"));this.previous=previous;this.host=host;this.root=root;this.label=label;}
 private static Component tr(String key,Object...args){return Component.translatable("mared.transition81."+key,args);}
 private Button button(String key,int x,int y,int width,Runnable action){return addRenderableWidget(Button.builder(tr(key),b->action.run()).bounds(x,y,width,20).build());}
 @Override protected void init(){w=Math.max(250,Math.min(700,width-24));left=(width-w)/2;int bw=(w-8)/3;wait=button("wait",left,36,bw,()->action("CONTINUE_WAIT"));stop=button("stop",left+bw+4,36,bw,()->confirm("stop_confirm",()->action("SHUTDOWN")));close=button("close",left+2*(bw+4),36,bw,()->confirm("close_confirm",()->action("CLOSE")));button("back",left,height-26,w,this::onClose);tick();}
 private Map<String,String> state(){var d=new TreeMap<String,String>();if(host){for(var e:DedicatedPanelService75.local().entrySet())try{d.put(e.getKey(),e.getValue().getAsString());}catch(Exception ignored){}}else d.putAll(DedicatedPanelService75.remote());return d;}
 private JsonObject control(){try{return JsonParser.parseString(state().getOrDefault("control","{}")).getAsJsonObject();}catch(Exception ignored){return new JsonObject();}}
 private JsonObject progress(){try{return control().getAsJsonObject("progress81");}catch(Exception ignored){return null;}}
 private boolean flag(JsonObject p,String name){try{return p!=null&&p.get(name).getAsBoolean();}catch(Exception ignored){return false;}}
 private void action(String action){if(host)DedicatedPanelService75.host("command",root,action.equals("SHUTDOWN")?"stop":action.toLowerCase(Locale.ROOT).replace('_','-'),"",label);else DedicatedPanelService75.request(action,label);}
 private void confirm(String text,Runnable action){minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes)action.run();},tr("confirm_title"),tr(text)));}
 @Override public void tick(){DedicatedPanelService75.poll(host,root);JsonObject p=progress();boolean busy=DedicatedPanelService75.busy();boolean live=false;try{long age=System.currentTimeMillis()-Long.parseLong(state().get("updated"));live=age<=10000&&age>= -30000;}catch(Exception ignored){}wait.active=!busy&&live&&flag(p,"canContinue")&&!flag(p,"closePending");close.active=!busy&&live&&flag(p,"canClose");var d=state();stop.active=!busy&&d.containsKey("phase")&&!Set.of("STOPPED_SAVED","STOP_NOT_CONFIRMED","FAILED").contains(d.get("phase"));}
 @Override public void onClose(){minecraft.setScreen(previous);}@Override public boolean isPauseScreen(){return false;}
 @Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*24)));return true;}
 private List<Component> lines(){var out=new ArrayList<Component>();out.add(tr("scope"));var d=state();if(d.containsKey("phase"))out.add(Component.translatable("mared.dedicated75.phase."+d.get("phase")));out.add(tr("result",Component.translatable("mared.dedicated75.result."+DedicatedPanelService75.result())));JsonObject p=progress();if(p==null){out.add(tr("no_report"));return out;}
  try{out.add(tr("time",Long.parseLong(p.get("elapsedMs").getAsString())/1000,Long.parseLong(p.get("idleMs").getAsString())/1000));out.add(tr("installed",p.get("installed").getAsString(),p.get("total").getAsString(),p.get("missingInstall").getAsString()));out.add(tr("joined",p.get("joined").getAsString(),p.get("total").getAsString()));out.add(tr(flag(p,"targetReady")?"target_ready":"target_wait"));if(!flag(p,"fresh"))out.add(tr("stale"));if(flag(p,"stalled"))out.add(tr("stalled"));if(flag(p,"closePending"))out.add(tr("close_pending"));if(Long.parseLong(p.get("ackAgeMs").getAsString())>=0)out.add(tr("ack",Long.parseLong(p.get("ackAgeMs").getAsString())/1000));JsonObject c=control();if(c.has("needed"))out.add(tr("threshold",c.get("needed").getAsString()));String key=p.get("missingInstall").getAsInt()>0?"waitingInstall":"waitingJoin";if(c.has(key)){out.add(tr("waiting"));for(JsonElement entry:c.getAsJsonArray(key)){JsonObject row=entry.getAsJsonObject();out.add(tr("member",row.get("account").getAsString(),tr("member."+row.get("state").getAsString())));}}}catch(Exception ignored){}out.add(tr("no_skip"));return out;}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xF0151820);g.drawCenteredString(font,title,width/2,10,0xFFFFFFFF);var rows=new ArrayList<net.minecraft.util.FormattedCharSequence>();for(Component c:lines())rows.addAll(font.split(c,w-8));int top=64,bottom=Math.max(top,height-32),step=font.lineHeight+3;maxScroll=Math.max(0,rows.size()*step-(bottom-top));scroll=Math.min(scroll,maxScroll);if(bottom>top){g.enableScissor(left,top,left+w,bottom);int y=top-scroll;for(var row:rows){if(y+step>=top&&y<bottom)g.drawString(font,row,left,y,0xFFCCD0DC,false);y+=step;}g.disableScissor();}super.render(g,mx,my,dt);}
}
